Object.assign(TX.en,{report:'Medication report',reportSub:'Your medications and intake history at a glance',reportTitle:'PillPlan – Medication & Intake Report',reportCreate:'View report',reportPeriod:'Period',reportPreview:'Preview',reportPrint:'Print / save PDF',reportClose:'Close',reportCreated:'Created',reportPlanned:'Scheduled intakes',reportDocumented:'Documented',reportRate:'Documentation rate',reportMedicationList:'Medications in period',reportDaily:'Intake documentation',reportNoData:'No scheduled intakes were found for this period.',reportTimes:'Intake times',reportDisclaimer:'This report shows self-reported entries, not independently verified intakes. Open does not automatically mean missed. Documentation rate is not a measure of adherence. Historical timing colours do not establish actual intake times. No therapy or dosage advice.',reportLocal:'Created locally on this device. No automatic data transfer.',reportSaveHint:'To save a PDF in the iOS print dialog, open the page preview and use Share to save to Files.'});

function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=e=>{const d=e.target.result;if(!d.objectStoreNames.contains('meds'))d.createObjectStore('meds',{keyPath:'id'});if(!d.objectStoreNames.contains('events')){const s=d.createObjectStore('events',{keyPath:'eventId'});s.createIndex('slot','slot',{unique:false});s.createIndex('createdAt','createdAt',{unique:false})}if(!d.objectStoreNames.contains('meta'))d.createObjectStore('meta',{keyPath:'key'})};r.onsuccess=()=>{db=r.result;resolve(db)};r.onerror=()=>reject(r.error)})}
function tx(s,m='readonly'){return db.transaction(s,m).objectStore(s)}
function all(s){return new Promise((res,rej)=>{const r=tx(s).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
function getOne(s,k){return new Promise((res,rej)=>{const r=tx(s).get(k);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function rawPut(s,o){return new Promise((res,rej)=>{const r=tx(s,'readwrite').put(o);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
function clear(s){return new Promise((res,rej)=>{const r=tx(s,'readwrite').clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random()}
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function today(){return localDate()}
function addDays(ds,n){const d=new Date(ds+'T12:00:00');d.setDate(d.getDate()+n);return localDate(d)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function normalizeTimes(a){return [...new Set((a||[]).filter(Boolean))].sort()}
function slotKey(mid,date,time){return `${date}_${mid}_${time}`}
function pastDays(n){const o=[];for(let i=n-1;i>=0;i--)o.push(addDays(today(),-i));return o}
function daysUntil(dateStr){if(!dateStr)return null;return Math.ceil((new Date(dateStr+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000)}
function deviceTimeZone(){try{return Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'}catch(_e){return'UTC'}}
function planTimeZone(){return localStorage.getItem('pillplan_timezone')||deviceTimeZone()}
function ensureInitialTimeZone(){if(!localStorage.getItem('pillplan_timezone'))localStorage.setItem('pillplan_timezone',deviceTimeZone())}
function timeZoneChanged(){return planTimeZone()!==deviceTimeZone()}
