function appendDocumentation(mid,date,time,type,details={},expectedEventId=undefined){
 return new Promise((resolve,reject)=>{
  const transaction=db.transaction(['meds','events'],'readwrite');let failure,result;
  transaction.oncomplete=()=>resolve(result);transaction.onabort=()=>reject(failure||transaction.error||Error(tr('writeFail')));transaction.onerror=()=>{};
  const events=transaction.objectStore('events'),mr=transaction.objectStore('meds').get(mid);
  mr.onsuccess=()=>{try{
   const med=mr.result;if(!timesForDate(med,date).includes(time))throw Error(tr('staleEntry'));
   const er=events.getAll();er.onsuccess=()=>{try{
    const rows=er.result.sort(compareEvents),slot=slotKey(mid,date,time),cur=rows.filter(e=>e.slot===slot).at(-1);
    if(expectedEventId!==undefined&&(cur?.eventId??null)!==expectedEventId)throw Error(tr('staleEntry'));
    if(!['taken','not_taken','unknown','undo'].includes(type))throw Error(tr('writeFail'));
    const now=new Date(),sequence=Math.max(0,...rows.map(e=>e.sequence||0))+1;
    if(!Number.isSafeInteger(sequence))throw Error(tr('writeFail'));
    result={...details,...planSnapshot(med,date,time),eventId:uid(),slot,type,tier:'unrated',documentationVersion:2,sequence,createdAt:now.toISOString(),documentedAt:now.toISOString(),timeZone:deviceTimeZone(),supersedesEventId:cur?.eventId??null};
    events.add(result);
   }catch(e){failure=e;transaction.abort()}};
  }catch(e){failure=e;transaction.abort()}};
 });
}
