const pendingSlots=new Set();
async function saveDocumentation(mid,date,time,type,details,expectedEventId){
 const slot=slotKey(mid,date,time);if(pendingSlots.has(slot))return false;pendingSlots.add(slot);
 try{await appendDocumentation(mid,date,time,type,details,expectedEventId);await render();return true}
 catch(e){alert(e.message||tr('writeFail'));return false}finally{pendingSlots.delete(slot)}
}
function timesForDate(m,ds){if(!m)return[];if(m.startDate&&ds<m.startDate)return[];if(m.endDate&&ds>m.endDate)return[];const h=(m.scheduleHistory||[]).filter(x=>x&&x.from&&Array.isArray(x.times)).slice().sort((a,b)=>a.from.localeCompare(b.from));let t=null;for(const x of h){if(x.from<=ds)t=x.times;else break}return normalizeTimes(t===null?(m.times||[]):t)}
function upsertSchedule(m,from,times){const h=(m.scheduleHistory||[]).slice(),i=h.findIndex(x=>x.from===from),e={from,times:normalizeTimes(times)};if(i>=0)h[i]=e;else h.push(e);h.sort((a,b)=>a.from.localeCompare(b.from));m.scheduleHistory=h}
function tierClass(e){const tier=visualTier(e);return tier==='green'?'done':tier==='yellow'?'tier-yellow':tier==='red'?'tier-red':tier==='open'?'':'unrated'}
