async function streak(){const meds=await all('meds'),map=await latestEvents();let s=0;for(let i=0;i<365;i++){const ds=addDays(today(),-i);let due=0,ok=true;for(const m of meds)for(const t of timesForDate(m,ds)){due++;if(map[slotKey(m.id,ds,t)]?.type!=='taken')ok=false}if(!due)continue;if(ok)s++;else break}return s}
function classifyDay(m,d,map){const ts=timesForDate(m,d);if(!ts.length)return'pre';const tiers=ts.map(t=>visualTier(map[slotKey(m.id,d,t)]));if(tiers.every(t=>t==='open'))return'';if(tiers.every(t=>['green','yellow','red','unrated'].includes(t))){if(tiers.includes('red'))return'red';if(tiers.includes('yellow'))return'yellow';if(tiers.every(t=>t==='green'))return'green';return'unrated'}if(tiers.every(t=>t==='green'||t==='unrated'))return'unrated';return'partial'}
