async function buildStats(n=30){const meds=await all('meds'),map=await latestEvents(),o={green:0,unrated:0,not_taken:0,unknown:0,open:0,due:0,done:0};for(const d of pastDays(n))for(const m of meds)for(const t of timesForDate(m,d)){o.due++;const tier=eventTier(map[slotKey(m.id,d,t)]);o[tier]++;if(tier==='green'||tier==='unrated')o.done++}o.pct=o.due?Math.round(o.done/o.due*100):0;return o}
