  const t=db.transaction(BACKUP_STORES,'readwrite');let mismatch=false;
  t.oncomplete=()=>resolve();t.onabort=()=>reject(Error(mismatch?bk('changed'):(t.error?.message||'Backup import failed')));t.onerror=()=>{};
