function reportTierLabel(e,date,time,now){return statusText(e,date,time,now)}
function reportWorstTier(a,b){
  const rank={open:5,unknown:4,not_taken:3,unrated:2,green:1};
  return (rank[b]||0)>(rank[a]||0)?b:a;
}
// Single Source of Truth for report data: preview and print/PDF consume this same model.
async function buildMedicationReport(daysCount=7){
  const meds=await all('meds'),map=await latestEvents(),days=pastDays(daysCount),reportClock=new Date();
  const stats={due:0,done:0,green:0,unrated:0,not_taken:0,unknown:0,open:0};
  const medicationRows=[];
  const dayRows=[];
  for(const m of meds){
    const relevant=days.filter(d=>timesForDate(m,d).length);
    if(!relevant.length)continue;
    const allTimes=normalizeTimes(relevant.flatMap(d=>timesForDate(m,d)));
    medicationRows.push({
      name:m.name,dose:m.dose||'',instructions:m.doctorInstructions||'',expiryDate:m.expiryDate||'',times:allTimes
    });
  }
  for(const d of days){
    for(const m of meds){
      for(const time of timesForDate(m,d)){
        stats.due++;
        const e=map[slotKey(m.id,d,time)];
        const tier=eventTier(e);stats[tier]++;if(e?.type==='taken')stats.done++;
        dayRows.push({date:d,name:m.name,dose:m.dose||'',time,tier:visualTier(e),label:reportTierLabel(e,d,time,reportClock),plannedTime:e?.plannedAtLocal||d+'T'+time,plannedZone:e?.planTimeZone||null,actualTime:e?.type==='taken'?actualTimeText(e):'—',recordedTime:recordedTimeText(e)});
      }
    }
  }
  stats.pct=stats.due?Math.round(stats.done/stats.due*100):0;
  return{daysCount,start:days[0],end:days[days.length-1],stats,medicationRows,dayRows,createdAt:reportClock.toISOString(),createdZone:planTimeZone()};
}
