// Single renderer for the medication report. Output channels must not implement their own report logic.
function reportHTML(r){
  const meds=r.medicationRows.length?r.medicationRows.map(m=>`<div class="pp-report-med"><b>${esc(m.name)}${m.dose?' · '+esc(m.dose):''}</b><div>${tr('reportTimes')}: ${esc(m.times.join(' · '))}</div>${m.instructions?`<div>${esc(m.instructions)}</div>`:''}${m.expiryDate?`<div>${tr('expiry')}: ${esc(reportDate(m.expiryDate))}</div>`:''}</div>`).join(''):`<div class="pp-report-med">${tr('reportNoData')}</div>`;
  const rows=r.dayRows.map(x=>`<tr><td>${esc(reportDate(x.date))}</td><td>${esc(x.name)}${x.dose?' '+esc(x.dose):''}</td><td>${esc(x.time)}${x.plannedZone?' ('+esc(x.plannedZone)+')':''}<br>${tr('actualTime')}: ${esc(x.actualTime)}<br>${tr('recordedTime')}: ${esc(x.recordedTime)}</td><td><span class="pp-report-status ${esc(x.tier)}">${esc(x.label)}</span></td></tr>`).join('');
  return `<section class="pp-report-sheet" id="pp-report-sheet"><div class="pp-report-title">${tr('reportTitle')}</div><div class="pp-report-meta">${tr('reportCreated')}: ${esc(localInZone(new Date(r.createdAt),r.createdZone).replace('T',' '))} · ${esc(reportDate(r.start))} – ${esc(reportDate(r.end))} · ${esc(planTimeZone())}</div><div class="pp-report-kpis"><div class="pp-report-kpi"><b>${r.stats.due}</b><span>${tr('reportPlanned')}</span></div><div class="pp-report-kpi"><b>${r.stats.done}</b><span>${tr('reportDocumented')}</span></div><div class="pp-report-kpi"><b>${r.stats.pct}%</b><span>${tr('reportRate')}</span></div></div><p class="pp-report-meta">${esc(tr('plannedRateHint'))}</p><div class="pp-report-h">${tr('reportMedicationList')}</div>${meds}<div class="pp-report-h">${tr('reportDaily')}</div>${rows?`<table class="pp-report-table"><thead><tr><th>Datum</th><th>${tr('medication')}</th><th>${tr('plannedTime')} / ${tr('actualTime')} / ${tr('recordedTime')}</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table>`:`<div class="pp-report-med">${tr('reportNoData')}</div>`}<div class="pp-report-disclaimer"><b>PillPlan</b> · ${esc(tr('reportLocal'))}<br><br>${esc(tr('reportSaveHint'))}<br><br>${esc(tr('reportDisclaimer'))}</div></section>`;
}



